// Browser-local knowledge demo. Shared persistence and authorization use FastAPI.
(function(){
 const page=document.createElement('main');page.id='knowledgePage';page.className='main';page.hidden=true;const header=document.createElement('div'),host=document.createElement('div');page.append(header,host);document.querySelector('#listPage').before(page);
 const nav=document.createElement('div');nav.className='dashnav';nav.id='knowledgeNav';nav.role='button';nav.tabIndex=0;nav.textContent='지식자산';nav.onclick=()=>{selected='';showPage('knowledge');};nav.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showPage('knowledge');}};document.querySelector('#personalNav').after(nav);
 let selected='',drafts=new Map();
 function actor(){return window.ATDemoProfile?.()||{id:'demo:unconnected',name:'시연 사용자',role:'participant'};}
 function open(id){if(!data.some(p=>p.id===id))return;selected=id;closeModal();showPage('knowledge');}
 function draw(){header.replaceChildren();if(!selected){StepUI.knowledgeHub(host,{projects:data,onOpen:open});return;}const project=data.find(p=>p.id===selected);if(!project){selected='';draw();return;}const back=document.createElement('button');back.className='secondary';back.textContent='지식자산 목록';back.onclick=()=>{selected='';draw();};const title=document.createElement('h1');title.textContent=project.title;header.append(back,title);const a=actor();const writable=!project.archivedAt&&(a.role==='at-head'||a.role==='system-admin'||a.role==='team-lead'&&a.team===project.team||[project.po,project.pm,...String(project.members||'').split(/[,\n]/).map(s=>s.trim())].includes(a.name));StepUI.knowledgeEditor(host,{project,projects:data,demo:true,writable,onOpen:open,initialDraft:drafts.get(selected),onDraft:value=>drafts.set(project.id,value),onSave:async value=>{const current=data.find(p=>p.id===project.id);if((current._revision||0)!==(project._revision||0))throw new Error('과제가 변경되었습니다. 최신 기록을 다시 열고 확인해 주세요.');const errors=KnowledgeModel.validate(value,project.id,data);if(errors.length)throw new Error(errors[0]);const next={...current,_knowledge:{...value,updatedAt:new Date().toISOString(),updatedBy:a,revision:(current._knowledge?.revision||0)+1}};if(!ApprovalWorkflow.withActor(a,()=>persistRecords(data.map(p=>p.id===next.id?next:p))))throw new Error('저장하지 못했습니다. 입력은 유지됩니다.');drafts.delete(project.id);render();draw();return data.find(p=>p.id===project.id);}});}
 const previousShow=showPage;showPage=function(name){page.hidden=name!=='knowledge';nav.classList.toggle('selected',name==='knowledge');previousShow(name);if(name==='knowledge')draw();};
 const previousDetail=detail;detail=function(id){previousDetail(id);const button=document.createElement('button');button.className='secondary';button.textContent='경험·지식 연결';button.onclick=()=>open(id);document.querySelector('#dialog .actions').prepend(button);};
 // Explicitly labelled sample records; existing user edits are never overwritten.
 const targets=data.filter(p=>p._demoScenario).slice(0,3).filter(p=>!p._knowledge);if(targets.length){const ids=data.filter(p=>p._demoScenario).slice(0,3).map(p=>p.id);const next=data.map(p=>{if(!targets.some(t=>t.id===p.id))return p;const i=ids.indexOf(p.id);return {...p,_knowledge:{...KnowledgeModel.empty(),status:i===2?'draft':'published',problem:'[체험] 공정 데이터 형식 차이로 분석과 재검증이 반복되었습니다.',approach:'공통 데이터 정의를 만든 뒤 단계별로 샘플을 검증했습니다.',result:'[체험] 공통 검증 절차와 점검 항목을 정리했습니다. 실제 업무 성과 수치는 아닙니다.',lessons:'초기 데이터 품질 확인을 생략하면 후반 검증에서 재작업이 발생했습니다.',conditions:'동일 데이터 정의를 적용할 수 있는 환경에서 활용하고, 다른 Tech는 항목을 다시 검증해야 합니다.',nextSteps:'후속 과제에서 적용 범위를 확장하고 효과를 측정합니다.',relations:i>0?[{projectId:ids[i-1],type:'predecessor'}]:[],updatedAt:new Date().toISOString(),updatedBy:{id:'demo:sample',name:'체험 데이터'},revision:1}};});persistRecords(next);}
})();
